FOLDERS = ('native/include', 'native/src', 'native/tests')


def base() -> Path:
    """Round 24 moved "now" for this seal to the pre-fix24 snapshot (round 23 as shipped): build/fix24_native_history.py
    first proves today's bytes differ from it only by round 24's declared changes."""
    import fix24_native_history
    fix24_native_history.verify()
    return fix24_native_history.SNAP


def _sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def check(rel: str, data: bytes) -> None:
    state, sha, why = FILES[rel]
    assert _sha(data) == sha, (rel, state, 'differs from the sealed bytes (edited after sealing; regenerate with a reason)')


def verify() -> dict:
    root = base()
    for rel in FILES:
        path = root / rel
        assert path.is_file(), (rel, 'sealed file is missing')
        check(rel, path.read_bytes())
    for folder in FOLDERS:
        for path in (root / folder).glob('*.*'):
            rel = path.relative_to(root).as_posix()
            assert rel in FILES, (rel, 'new file in a sealed folder, not in the seal')
    return {s: sum(1 for v in FILES.values() if v[0] == s) for s in ('unchanged', 'changed', 'added')}


# Silent edits (a constant or a condition changed without resealing): each must fail check().
SILENT_EDITS = [
    ('native/include/Status.h', 'inline constexpr float kGuardShare = 0.5f;', 'inline constexpr float kGuardShare = 0.6f;'),
    ('native/include/SelfLayer.h', 'plan.Push(res::Discharge(before, 1.0f, n4::kPower, n4::kPowerCrit));',
     'plan.Push(res::Discharge(before, 1.0f, n4::kPower, 1.5f));'),
    ('native/include/Hurt.h', 'blocked = lost * share.share / (1.0f - share.share);', 'blocked = lost * share.share;'),
    ('build_v03.py', 'GUARD_SHARE = 0.50', 'GUARD_SHARE = 0.60'),
    ('build/fix23_records.py', 'HOLY_MR = [10.0, 20.0, 35.0]', 'HOLY_MR = [10.0, 20.0, 30.0]'),
]


def self_check() -> dict:
    counts = verify()
    caught = []
    for rel, old, new in SILENT_EDITS:
        data = (base() / rel).read_bytes()
        assert old.encode('utf-8') in data, (rel, old)
        try:
            check(rel, data.replace(old.encode('utf-8'), new.encode('utf-8'), 1))
        except AssertionError:
            caught.append(rel)
            continue
        raise AssertionError(('silent edit not caught', rel, old))
    return dict(counts, silent_edits_caught=caught)
